using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API for a given resource path.")]
    public static async Task<string> FetchDataAsync(
        HttpClient httpClient,
        [Description("The API resource path to query, e.g. 'users/1'.")] string path,
        CancellationToken cancellationToken)
    {
        using var response = await httpClient.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        using var doc = await JsonDocument.ParseAsync(
            await response.Content.ReadAsStreamAsync(cancellationToken),
            cancellationToken: cancellationToken);

        return JsonSerializer.Serialize(doc.RootElement, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text content to summarize.")] string text,
        [Description("Optional maximum length constraint, e.g. '2 sentences'.")] string? maxLength = null)
    {
        var constraint = string.IsNullOrWhiteSpace(maxLength)
            ? string.Empty
            : $" Keep the summary within {maxLength}.";

        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"Please summarize the following text concisely.{constraint}\n\n{text}"
                }
            }
        ];
    }
}

